Here is the commit message:
udp: fix SO_BINDTODEVICE

Damir reported a breakage of SO_BINDTODEVICE for UDP sockets.
In absence of VRF devices, after commit fb74c27735f0 ("net:
ipv4: add second dif to udp socket lookups") the dif mismatch
isn't fatal anymore for UDP socket lookup with non null
sk_bound_dev_if, breaking SO_BINDTODEVICE semantics.

This changeset addresses the issue making the dif match mandatory
again in the above scenario.

Reported-by: Damir Mansurov <dnman@oktetlabs.ru>
Fixes: fb74c27735f0 ("net: ipv4: add second dif to udp socket lookups")
Fixes: 1801b570dd2a ("net: ipv6: add second dif to udp socket lookups")
Signed-off-by: Paolo Abeni <pabeni@redhat.com>
Acked-by: David Ahern <dsahern@gmail.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by a change in the UDP socket lookup mechanism that made the device interface match (`dif`) non-fatal for UDP sockets when `sk_bound_dev_if` was non-null. This change allowed mismatches in the device interface to occur without causing an error, which broke the expected behavior of the `SO_BINDTODEVICE` socket option, leading to incorrect socket binding semantics.

Here is the patch:

 static int compute_score(struct sock *sk, struct net *net,
 			 __be32 saddr, __be16 sport,
 			 __be32 daddr, unsigned short hnum,
 			 int dif, int sdif, bool exact_dif)
 {
 	int score;
 	struct inet_sock *inet;

 	if (!net_eq(sock_net(sk), net) ||
 	    udp_sk(sk)->udp_port_hash != hnum ||
 	    ipv6_only_sock(sk))
 		return -1;

 	score = (sk->sk_family == PF_INET) ? 2 : 1;
 	inet = inet_sk(sk);

 	if (inet->inet_rcv_saddr) {
 		if (inet->inet_rcv_saddr != daddr)
 			return -1;
 		score += 4;
 	}

 	if (inet->inet_daddr) {
 		if (inet->inet_daddr != saddr)
 			return -1;
 		score += 4;
 	}

 	if (inet->inet_dport) {
 		if (inet->inet_dport != sport)
 			return -1;
 		score += 4;
 	}

 	if (sk->sk_bound_dev_if || exact_dif) {
 		bool dev_match = (sk->sk_bound_dev_if == dif ||
 				  sk->sk_bound_dev_if == sdif);

-		if (exact_dif && !dev_match)
+		if (!dev_match)
 			return -1;
-		if (sk->sk_bound_dev_if && dev_match)
+		if (sk->sk_bound_dev_if)
 			score += 4;
 	}

 	if (sk->sk_incoming_cpu == raw_smp_processor_id())
 		score++;
 	return score;
 }



